using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Text;using System.Text.RegularExpressions;
namespace PZ3D {
 sealed class LauncherTaskEvent {public string at,message;public int progress;}
 sealed class LauncherTaskRecord {public string id,action,title,started,finished,status,message;public int progress=-1,ownerPid;public long ownerBirth;public List<LauncherTaskEvent> events=new List<LauncherTaskEvent>();}
 sealed class LauncherTaskStore {public int version=1;public List<LauncherTaskRecord> history=new List<LauncherTaskRecord>();}
 sealed class LauncherJournal {
  readonly string file,logFile;string activeId;
  public LauncherJournal(string data){file=Path.Combine(data,"diagnostics","tasks.json");logFile=Path.Combine(data,"diagnostics","launcher.log");LauncherNativeState.Locked(file,()=>{var s=Read();bool changed=false;foreach(var task in s.history.Where(t=>t.status=="running")){if(!OwnerAlive(task)){task.status="interrupted";task.finished=DateTime.UtcNow.ToString("o");task.message="上次任务中断；实际文件状态请在对应页面刷新核对。";changed=true;}}if(changed)Save(s);return true;});}
  LauncherTaskStore Read(){var s=LauncherNativeState.Read(file,()=>new LauncherTaskStore());if(s==null||s.version!=1||s.history==null||s.history.Count>60||s.history.Any(t=>t==null||t.events==null||t.events.Count>120))throw new Exception("任务记录无效，未覆盖。");return s;}
  static bool OwnerAlive(LauncherTaskRecord r){try{using(var p=Process.GetProcessById(r.ownerPid))return !p.HasExited&&p.StartTime.ToUniversalTime().Ticks==r.ownerBirth;}catch{return false;}}
  public static string Sanitize(string text){string clean=ScrubText(text??"",0);return new string(clean.Where(c=>!char.IsControl(c)||c=='\n'||c=='\t').Take(4000).ToArray());}
  static readonly Regex SensitiveKey=new Regex(@"(?i)^(password|passwd|userPassword|serverPassword|token|ticket|authorization|userCipher|serverCipher)$");
  static object ScrubObject(object value,int depth){if(depth>8)return "[深层内容已隐藏]";var map=value as Dictionary<string,object>;if(map!=null){var safe=new Dictionary<string,object>();foreach(var p in map)safe[p.Key]=SensitiveKey.IsMatch(p.Key)?"[已隐藏]":ScrubObject(p.Value,depth+1);return safe;}var array=value as object[];if(array!=null)return array.Select(v=>ScrubObject(v,depth+1)).ToArray();if(value is string)return ScrubText((string)value,depth+1);return value;}
  static string ScrubText(string text,int depth){if(depth>8)return "[深层内容已隐藏]";if(text.Length>65536)text=text.Substring(0,65536);string trim=text.TrimStart();if(trim.StartsWith("{")||trim.StartsWith("[")){try{var j=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=65536,RecursionLimit=24};return j.Serialize(ScrubObject(j.DeserializeObject(text),depth+1));}catch{}}
   text=Regex.Replace(text,@"(?i)(password|passwd|userPassword|serverPassword|token|ticket|authorization|userCipher|serverCipher)(?:\\*[""'])?\s*[=:][^\r\n]*","$1=[已隐藏]");return Regex.Replace(text,@"(?i)(connect|login)\s+[^\r\n]*","$1 [连接参数已隐藏]");}
  public string Begin(string action,string title){return LauncherNativeState.Locked(file,()=>{var s=Read();using(var p=Process.GetCurrentProcess()){var r=new LauncherTaskRecord{id=Guid.NewGuid().ToString("N"),action=Sanitize(action),title=Sanitize(title),started=DateTime.UtcNow.ToString("o"),status="running",message="正在准备",ownerPid=p.Id,ownerBirth=p.StartTime.ToUniversalTime().Ticks};s.history.Insert(0,r);s.history=s.history.Take(50).ToList();activeId=r.id;Save(s);Append(r.title+" · 开始");return r.id;}});}
  public void Update(int progress,string message){if(activeId==null)return;LauncherNativeState.Locked(file,()=>{var s=Read();var r=s.history.FirstOrDefault(x=>x.id==activeId);if(r==null||r.status!="running")return false;r.progress=progress<0?-1:Math.Min(100,progress);r.message=Sanitize(message);r.events.Add(new LauncherTaskEvent{at=DateTime.UtcNow.ToString("o"),progress=r.progress,message=r.message});r.events=r.events.Skip(Math.Max(0,r.events.Count-100)).ToList();Save(s);Append(r.message);return true;});}
  public void Finish(string status,string message){if(!new[]{"completed","partial","failed","cancelled"}.Contains(status))throw new Exception("无效任务结果。");if(activeId==null)return;LauncherNativeState.Locked(file,()=>{var s=Read();var r=s.history.FirstOrDefault(x=>x.id==activeId);if(r==null)return false;r.status=status;r.finished=DateTime.UtcNow.ToString("o");r.message=Sanitize(message);if(status=="completed")r.progress=100;else if(r.progress==100)r.progress=-1;Save(s);Append(r.title+" · "+status+" · "+r.message);activeId=null;return true;});}
  void Save(LauncherTaskStore store){while(Encoding.UTF8.GetByteCount(LauncherNativeState.Json.Serialize(store))>1400000){if(store.history.Count>1)store.history.RemoveAt(store.history.Count-1);else if(store.history.Count==1&&store.history[0].events.Count>1)store.history[0].events.RemoveAt(0);else throw new Exception("任务记录超过容量限制。");}LauncherNativeState.Write(file,store);}
  public void Diagnostic(string message){LauncherNativeState.Locked(file,()=>{Append(message);return true;});}
  void Append(string message){LauncherMaintenance.NoReparse(logFile);Directory.CreateDirectory(Path.GetDirectoryName(logFile));if(File.Exists(logFile)&&new FileInfo(logFile).Length>1048576){string previous=logFile+".previous";LauncherMaintenance.NoReparse(previous);if(File.Exists(previous))File.Delete(previous);File.Move(logFile,previous);}File.AppendAllText(logFile,DateTime.UtcNow.ToString("o")+" "+Sanitize(message)+Environment.NewLine,new UTF8Encoding(false));}
  public object Snapshot(){return LauncherNativeState.Locked(file,()=>{var s=Read();return (object)new{active=s.history.FirstOrDefault(r=>r.status=="running"&&OwnerAlive(r)),history=s.history.Take(40).ToArray(),logPath=Path.GetDirectoryName(file)};});}
 }
}
